from typing import List

class Solution:
    def maxFrequency(self, nums: List[int], k: int) -> int:
        base = nums.count(k)
        ans = base

        for v in range(1, 51):
            if v == k:
                continue

            cur = 0
            best = 0

            for num in nums:
                if num == v:
                    delta = 1
                elif num == k:
                    delta = -1
                else:
                    delta = 0

                cur = max(0, cur + delta)
                best = max(best, cur)

            ans = max(ans, base + best)

        return ans
